import{_ as o,r as n,o as p,c,e as a,a as r,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Users - October CMS - 4.x","titleTemplate":false,"description":"Learn about user management in the backend panel.","frontmatter":{"subtitle":"Learn about user management in the backend panel."},"headers":[{"level":2,"title":"Backend User Helper","slug":"backend-user-helper","link":"#backend-user-helper","children":[]},{"level":2,"title":"Groups","slug":"groups","link":"#groups","children":[]},{"level":2,"title":"Change Backend User Password","slug":"change-backend-user-password","link":"#change-backend-user-password","children":[]}],"relativePath":"4.x/extend/backend/users.md","filePath":"4.x/extend/backend/users.md"}'),l={name:"4.x/extend/backend/users.md"};function u(d,s,g,k,h,m){const e=n("pre-heading"),t=n("post-heading");return p(),c("div",null,[a(e),s[0]||(s[0]=r("h1",null,"Users",-1)),a(t),s[1]||(s[1]=i(`<p>The user management for the backend panel works with administrators where the <code>Backend\\Models\\User</code> model is the container that hold all the important information about a user. It includes features like roles, groups, permissions, password resets and sign-in throttling. Plugins can also <a href="./permissions.html">register permissions</a> that control access to the features in the backend.</p><h2 id="backend-user-helper"><a href="#backend-user-helper" class="header-anchor">#</a> Backend User Helper</h2><p>The global <code>BackendAuth</code> facade can be used for managing administrative users, which primarily inherits the <code>October\\Rain\\Auth\\Manager</code> class. To register a new administrator user account, use the <code>BackendAuth::register</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;first_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Some&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;last_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;someuser&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;some@website.tld&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;changeme&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;changeme&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>BackendAuth::check</code> method is a quick way to check if the user is signed in. To return the user model that is signed in, use <code>BackendAuth::getUser</code> instead. Additionally, the active user will be available as <code>$this-&gt;user</code> inside any <a href="./../system/controllers.html">backend controller</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns true if signed in.</span>
<span class="token variable">$loggedIn</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">check</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Returns the signed in user</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">getUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may look up a user by their login name using the <code>BackendAuth::findUserByLogin</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">findUserByLogin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;someuser&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may authenticate a user by providing their login and password with <code>BackendAuth::authenticate</code>. You can also authenticate as a user simply by passing the <code>Backend\\Models\\User</code> model along with <code>BackendAuth::login</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Authenticate user by credentials</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">authenticate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;login&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Sign in as a specific user</span>
<span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">login</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="groups"><a href="#groups" class="header-anchor">#</a> Groups</h2><p>User groups use the <code>Backend\\Models\\UserGroup</code> model and are an organizational tool for grouping administrators, they are not related to <a href="./permissions.html">user permissions</a> and are strictly for organizational purposes, such as notifications.</p><p>For instance, if you wanted to send an email to all users that are in the group <code>Head Office Staff</code>, you could find the user group along with the users in that group.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$group</span> <span class="token operator">=</span> <span class="token class-name static-context">UserGroup</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;code&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;head-office-staff&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$group</span><span class="token operator">-&gt;</span><span class="token property">users</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;author.plugin:important_notification&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="change-backend-user-password"><a href="#change-backend-user-password" class="header-anchor">#</a> Change Backend User Password</h2><p>The <code>october:passwd</code> command allows the password of a backend administrator to be changed via the command line. This is useful if you are locked out of your October CMS install, or for changing the password for the default administrator account.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:passwd username password
</code></pre></div><p>For the first argument you may pass either the login name or email address. For the second argument you may optionally pass the desired password, otherwise you will be prompted to enter one.</p>`,18))])}const w=o(l,[["render",u]]);export{b as __pageData,w as default};
